// Valida y normaliza el pedido que llega desde la página.
// Los montos se recalculan aquí: no se confía en los totales que manda el navegador.
const CONFIG = {
  correoAdmin: 'bryangomezfwd@gmail.com',
  whatsappAdmin: '+50662848105', // número que activó CallMeBot
  porcentajeIva: 13,
  maxLineas: 50,
};

const EMISOR = {
  nombreComercial: 'Avrill · Un spa en casa',
  nombre: 'Avrill',
  cedula: '3-101-000000',
  telefono: '+506 6284-8105',
  correo: 'contacto@avrillcr.com',
  direccion: 'San José, Desamparados, Centro de Desamparados',
  condicionVenta: 'Contado',
  medioPago: 'Efectivo / SINPE Móvil',
};

const body = $json.body || {};
const origen = body.cliente || body.factura?.receptor || {};

const texto = (valor, max) =>
  String(valor ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const esc = (valor) =>
  String(valor ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const redondear = (n) => Math.round(n * 100) / 100;
const crc = (n) => '₡' + Number(n).toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const errores = [];

const cliente = {
  nombre: texto(origen.nombre, 60),
  correo: texto(origen.correo, 100).toLowerCase(),
  telefono: String(origen.telefono ?? '').replace(/\D/g, '').slice(0, 15),
  identificacion: String(origen.identificacion ?? '').replace(/\D/g, '').slice(0, 12),
  direccion: texto(origen.direccion, 150),
  coordenadas: null,
};

const lat = Number(origen.coordenadas?.lat);
const lng = Number(origen.coordenadas?.lng);
if (Number.isFinite(lat) && Number.isFinite(lng) && Math.abs(lat) <= 90 && Math.abs(lng) <= 180) {
  cliente.coordenadas = { lat, lng };
}

if (cliente.nombre.length < 3) errores.push('Nombre del cliente inválido.');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(cliente.correo)) errores.push('Correo del cliente inválido.');
if (!/^\d{8,15}$/.test(cliente.telefono)) errores.push('Teléfono inválido.');
if (cliente.direccion.length < 5) errores.push('Dirección inválida.');

const lineasFactura = Array.isArray(body.factura?.lineas) && body.factura.lineas.length
  ? body.factura.lineas.map((l) => ({ codigo: l.codigo, descripcion: l.descripcion, cantidad: l.cantidad, precio: l.precioUnitario }))
  : (Array.isArray(body.productos) ? body.productos : []).map((p) => ({ codigo: p.id, descripcion: p.nombre, cantidad: p.cantidad, precio: p.precio }));

if (lineasFactura.length === 0) errores.push('El pedido no tiene productos.');
if (lineasFactura.length > CONFIG.maxLineas) errores.push('El pedido tiene demasiadas líneas.');

const lineas = lineasFactura.slice(0, CONFIG.maxLineas).map((l) => {
  const cantidad = Math.trunc(Number(l.cantidad) || 1);
  const precio = Number(l.precio);
  if (cantidad < 1 || cantidad > 99) errores.push('Cantidad inválida en: ' + texto(l.descripcion, 60));
  if (!Number.isFinite(precio) || precio < 0 || precio > 10000000) errores.push('Precio inválido en: ' + texto(l.descripcion, 60));
  return {
    codigo: texto(l.codigo, 20),
    descripcion: texto(l.descripcion, 80),
    cantidad,
    precioUnitario: precio,
    monto: redondear(precio * cantidad),
  };
});

if (errores.length) {
  return [{ json: { valido: false, errores } }];
}

// Igual que src/utils/factura.js: los precios ya incluyen el IVA.
const total = redondear(lineas.reduce((suma, l) => suma + l.monto, 0));
const iva = redondear((total * CONFIG.porcentajeIva) / (100 + CONFIG.porcentajeIva));
const subtotal = redondear(total - iva);

const fechaIso = !Number.isNaN(Date.parse(body.fecha)) ? new Date(body.fecha).toISOString() : new Date().toISOString();
const fechaTexto = new Date(fechaIso).toLocaleString('es-CR', {
  timeZone: 'America/Costa_Rica', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
});
const numero = texto(body.factura?.numero, 30).replace(/[^A-Za-z0-9-]/g, '')
  || `PF-${new Date(fechaIso).getFullYear()}-${String(Number(body.id) || Date.now()).slice(-5)}`;

const ubicacion = cliente.coordenadas
  ? `https://www.google.com/maps?q=${cliente.coordenadas.lat},${cliente.coordenadas.lng}`
  : '';

const td = 'padding:8px;border-bottom:1px solid #e8e2d8;';
const filas = lineas.map((l) => `
  <tr>
    <td style="${td}">${esc(l.codigo)}</td>
    <td style="${td}">${esc(l.descripcion)}</td>
    <td style="${td}text-align:center;">${l.cantidad}</td>
    <td style="${td}text-align:right;">${crc(l.precioUnitario)}</td>
    <td style="${td}text-align:right;">${crc(l.monto)}</td>
  </tr>`).join('');

const th = 'background:#4a5d4e;color:#ffffff;font-size:12px;padding:8px;text-transform:uppercase;';
const facturaHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#191c1a;font-size:13px;line-height:1.5;max-width:720px;margin:0 auto;">
  <table width="100%" style="border-bottom:3px solid #4a5d4e;padding-bottom:12px;">
    <tr>
      <td><h2 style="margin:0;color:#334537;">${esc(EMISOR.nombreComercial)}</h2>
        <small style="color:#6e7570;">Factura proforma · No es un comprobante electrónico</small></td>
      <td style="text-align:right;"><strong>Factura Proforma ${esc(numero)}</strong><br>
        <span style="color:#6e7570;">${esc(fechaTexto)}</span></td>
    </tr>
  </table>
  <table width="100%" style="margin-top:12px;">
    <tr>
      <td style="vertical-align:top;width:50%;padding-right:8px;">
        <strong style="color:#4a5d4e;">EMISOR</strong><br>
        ${esc(EMISOR.nombre)} · Cédula ${esc(EMISOR.cedula)}<br>
        Tel: ${esc(EMISOR.telefono)}<br>
        ${esc(EMISOR.correo)}<br>
        ${esc(EMISOR.direccion)}
      </td>
      <td style="vertical-align:top;width:50%;">
        <strong style="color:#4a5d4e;">RECEPTOR</strong><br>
        ${esc(cliente.nombre)}<br>
        Identificación: ${esc(cliente.identificacion || 'Sin especificar')}<br>
        Tel: ${esc(cliente.telefono)}<br>
        ${esc(cliente.correo)}<br>
        ${esc(cliente.direccion)}
      </td>
    </tr>
  </table>
  <p style="margin:12px 0 0;color:#6e7570;">Condición: ${esc(EMISOR.condicionVenta)} · Medio de pago: ${esc(EMISOR.medioPago)} · Moneda: CRC</p>
  <table width="100%" cellspacing="0" style="border-collapse:collapse;margin-top:12px;">
    <thead><tr>
      <th style="${th}text-align:left;">Código</th>
      <th style="${th}text-align:left;">Descripción</th>
      <th style="${th}text-align:center;">Cant.</th>
      <th style="${th}text-align:right;">Precio unit.</th>
      <th style="${th}text-align:right;">Monto</th>
    </tr></thead>
    <tbody>${filas}</tbody>
  </table>
  <table style="margin:12px 0 0 auto;min-width:280px;">
    <tr><td>Subtotal (sin impuestos)</td><td style="text-align:right;"><strong>${crc(subtotal)}</strong></td></tr>
    <tr><td>IVA ${CONFIG.porcentajeIva}%</td><td style="text-align:right;"><strong>${crc(iva)}</strong></td></tr>
    <tr><td style="border-top:2px solid #4a5d4e;padding-top:6px;font-size:15px;"><strong>Total</strong></td>
        <td style="border-top:2px solid #4a5d4e;padding-top:6px;font-size:15px;text-align:right;"><strong>${crc(total)}</strong></td></tr>
  </table>
  <p style="background:#faf6f0;border-left:4px solid #a96447;color:#6e7570;font-size:11px;margin-top:16px;padding:10px 12px;">
    Documento sin validez fiscal ante el Ministerio de Hacienda de Costa Rica. Corresponde a una factura proforma.
    Los precios incluyen el IVA (${CONFIG.porcentajeIva}%).
  </p>
</div>`;

return [{
  json: {
    valido: true,
    numero,
    fecha: fechaIso,
    fechaTexto,
    cliente,
    ubicacion,
    lineas,
    subtotal,
    iva,
    total,
    totalTexto: crc(total),
    facturaHtml,
    correoAdmin: CONFIG.correoAdmin,
    whatsappAdmin: CONFIG.whatsappAdmin,
    // Lo único que ve la IA: sin correo, teléfono, cédula ni dirección.
    resumenIA: {
      nombreCliente: cliente.nombre.split(' ')[0],
      numeroFactura: numero,
      productos: lineas.map((l) => `${l.cantidad} x ${l.descripcion}`),
      total: crc(total),
    },
  },
}];

// Une la redacción del Agente de Pedidos con los datos reales del pedido.
// Si DeepSeek falla o responde algo inválido se usan textos por defecto.
const p = $('Validar Pedido').first().json;

const esc = (valor) =>
  String(valor ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const limpiar = (valor, max) => String(valor ?? '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().slice(0, max);

let ia = {};
try {
  const crudo = String($json.output ?? '');
  const bloque = crudo.match(/\{[\s\S]*\}/);
  ia = bloque ? JSON.parse(bloque[0]) : {};
} catch (error) {
  ia = {};
}

const saludo = limpiar(ia.saludoCliente, 600)
  || `¡Hola ${p.resumenIA.nombreCliente}! Gracias por tu compra en Avrill · Un spa en casa. Adjuntamos tu factura proforma ${p.numero}; pronto te contactaremos para coordinar el pago y la entrega. 🌿`;
const notaAdmin = limpiar(ia.notaAdmin, 300);

const htmlCliente = `
<div style="font-family:Arial,Helvetica,sans-serif;background:#fdfbf7;padding:24px;">
  <div style="max-width:720px;margin:0 auto;background:#ffffff;border:1px solid #e8e2d8;border-radius:12px;padding:24px;">
    <p style="font-size:15px;color:#334537;">${esc(saludo)}</p>
    ${p.facturaHtml}
    <p style="color:#6e7570;font-size:12px;margin-top:20px;">
      ¿Dudas? Escríbenos a contacto@avrillcr.com o al WhatsApp +506 6284-8105.<br>
      Avrill · Un spa en casa · Desamparados, San José, Costa Rica
    </p>
  </div>
</div>`;

const c = p.cliente;
const filaDato = (etiqueta, valor) =>
  `<tr><td style="padding:4px 12px 4px 0;color:#6e7570;">${etiqueta}</td><td style="padding:4px 0;"><strong>${valor}</strong></td></tr>`;

const htmlAdmin = `
<div style="font-family:Arial,Helvetica,sans-serif;padding:16px;">
  <h2 style="color:#334537;margin:0 0 8px;">🛍️ Nueva compra de ${esc(c.nombre)}</h2>
  <p style="margin:0 0 12px;color:#6e7570;">Factura ${esc(p.numero)} · ${esc(p.fechaTexto)} · Total ${esc(p.totalTexto)}</p>
  <table>
    ${filaDato('Nombre', esc(c.nombre))}
    ${filaDato('Correo', esc(c.correo))}
    ${filaDato('Teléfono', esc(c.telefono))}
    ${filaDato('Identificación', esc(c.identificacion || 'Sin especificar'))}
    ${filaDato('Dirección', esc(c.direccion))}
    ${p.ubicacion ? filaDato('Ubicación', `<a href="${esc(p.ubicacion)}">Ver en Google Maps</a>`) : ''}
  </table>
  ${notaAdmin ? `<p style="background:#faf6f0;border-left:4px solid #c5a059;padding:8px 12px;">${esc(notaAdmin)}</p>` : ''}
  <hr style="border:none;border-top:1px solid #e8e2d8;margin:16px 0;">
  ${p.facturaHtml}
</div>`;

const productos = p.lineas.map((l) => `• ${l.cantidad} x ${l.descripcion}`).join('\n');

const mensajeWhatsApp = [
  `🛍️ *Nueva compra en Avrill*`,
  `Hay una nueva compra de *${c.nombre}*`,
  ``,
  `🧾 Factura: ${p.numero}`,
  `📅 Fecha: ${p.fechaTexto}`,
  ``,
  `👤 *Datos del cliente*`,
  `Nombre: ${c.nombre}`,
  `Correo: ${c.correo}`,
  `Teléfono: ${c.telefono}`,
  `Identificación: ${c.identificacion || 'Sin especificar'}`,
  `Dirección: ${c.direccion}`,
  p.ubicacion ? `Ubicación: ${p.ubicacion}` : null,
  ``,
  `📦 *Productos*`,
  productos,
  ``,
  `💰 *Total: ${p.totalTexto}* (IVA incluido)`,
  notaAdmin ? `\n📝 ${notaAdmin}` : null,
].filter((linea) => linea !== null).join('\n');

return [{
  json: {
    numero: p.numero,
    correoCliente: c.correo,
    correoAdmin: p.correoAdmin,
    whatsappAdmin: p.whatsappAdmin,
    asuntoCliente: `Tu factura proforma ${p.numero} · Avrill · Un spa en casa`,
    asuntoAdmin: `🛍️ Nueva compra de ${c.nombre} · ${p.numero} · ${p.totalTexto}`,
    htmlCliente,
    htmlAdmin,
    mensajeWhatsApp,
  },
}];

// Primera barrera del chat: limpia la entrada y bloquea, antes de llegar a la IA,
// los intentos de sacar datos sensibles o de cambiar las reglas del asistente.
const body = $json.body || {};

const texto = (valor, max) =>
  String(valor ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);

const mensaje = texto(body.mensaje, 500);
const sessionId = String(body.sessionId ?? '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64)
  || `anon-${Date.now()}`;

// Solo campos públicos del catálogo; cualquier otro campo que llegue se descarta.
const productos = (Array.isArray(body.productos) ? body.productos : []).slice(0, 100).map((p) => ({
  nombre: texto(p.nombre, 80),
  categoria: texto(p.categoria, 30),
  precio: Number(p.precio) || 0,
  disponible: p.disponible !== false,
  etiqueta: texto(p.etiqueta, 30),
  detalle: texto(p.detalle, 300),
})).filter((p) => p.nombre);

const catalogoTexto = productos.length
  ? productos.map((p) =>
      `- ${p.nombre} | categoría: ${p.categoria} | ₡${p.precio.toLocaleString('es-CR')} CRC | ${p.disponible ? 'disponible' : 'AGOTADO'}${p.etiqueta ? ' | ' + p.etiqueta : ''} | ${p.detalle}`
    ).join('\n')
  : '(No se recibió el catálogo. Invita al cliente a revisar la sección "Catálogo" de la página.)';

const patronesSensibles = [
  /contrase(n|ñ)a|password|passwd|clave (de |del )?(admin|acceso|usuario|la cuenta)/i,
  /api[\s_-]?key|\btokens?\b|\bsecret\b|credencial|\.env\b|db\.json|base de datos|database|\bhash\b|bcrypt|\bsql\b/i,
  /c[oó]digo (de )?descuento (del|de) (admin|administrador)/i,
  /ignora(r)? (tus|las|todas) (las )?(instrucciones|reglas)|ignore (all|previous|your)|system prompt|tu prompt|tus instrucciones|modo (desarrollador|developer)|jailbreak|\bDAN\b/i,
  /datos (personales )?(de|del) (otros? )?(clientes?|usuarios?|admin)|usuarios registrados|lista de (usuarios|clientes|pedidos)|correo del admin|tel[eé]fono (del|de) (otros? )?clientes?/i,
];

let bloqueado = false;
let respuesta = '';

if (!mensaje) {
  bloqueado = true;
  respuesta = 'Escríbeme tu consulta sobre nuestros productos, envíos o pedidos y con gusto te ayudo. 🌿';
} else if (patronesSensibles.some((patron) => patron.test(mensaje))) {
  bloqueado = true;
  respuesta = 'Por seguridad no puedo compartir información interna, credenciales ni datos de otros clientes. 🌿 Con gusto te ayudo con nuestros productos, envíos o tu pedido.';
}

return [{ json: { mensaje, sessionId, catalogoTexto, bloqueado, respuesta } }];

// Última barrera del chat: aunque la IA se equivoque, nada que parezca
// un secreto o un dato personal sale hacia el navegador.
const CORREO_PUBLICO = 'contacto@avrillcr.com';
const FUERA_DE_TEMA = 'Como boticaria virtual de Avrill, únicamente puedo ayudarte con nuestros productos artesanales, cuidado de la piel, pedidos y envíos. 🌿 ¿En qué te ayudo hoy?';

let respuesta = String($json.output ?? '').trim();

const secretos = [
  /\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}/g,               // hashes bcrypt
  /\bsk-[A-Za-z0-9_-]{16,}/g,                          // claves de API
  /\bpk\.[A-Za-z0-9_.-]{20,}/g,                        // tokens de Mapbox
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, // JWT
  /\bAVRILL[A-Z0-9]{4,}\b/g,                           // códigos de descuento internos
  /\b[A-Za-z0-9+/_-]{32,}={0,2}/g,                     // cadenas largas tipo token
];
for (const patron of secretos) {
  respuesta = respuesta.replace(patron, '[dato protegido]');
}

respuesta = respuesta.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, (correo) =>
  correo.toLowerCase() === CORREO_PUBLICO ? correo : '[dato protegido]'
);

if (!respuesta) respuesta = FUERA_DE_TEMA;

return [{ json: { respuesta: respuesta.slice(0, 1200) } }];
